import{_ as d,h as s,i as o,c as n,v as a,p as l,x as c,m as i,e as p,S as r}from"./chunks/framework.Dvtg8yj2.js";const E=JSON.parse('{"title":"OpenAI 兼容协议","description":"","frontmatter":{"title":"OpenAI 兼容协议","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/openai-compat-api.md","filePath":"llm/openai-compat-api.md","lastUpdated":1788454257000}'),m={name:"llm/openai-compat-api.md"};function h(A,e,u,_,I,g){const t=s("Mermaid");return o(),n("div",null,[e[1]||(e[1]=a('<h1 id="openai-兼容协议" tabindex="-1">OpenAI 兼容协议 <a class="header-anchor" href="#openai-兼容协议" aria-label="Permalink to &quot;OpenAI 兼容协议&quot;">​</a></h1><div class="epigraph"><p>客户端按 `/v1/chat/completions` 发 `messages`，服务端按同一套字段流式或一次性回 `choices`。兼容的是信封，不是某家闭源模型的权重。</p><footer>—— 对照 OpenAI API 参考与 TGI / vLLM / MindIE 的兼容层说明</footer></div><p>开源推理引擎几乎都提供一层「看起来像 OpenAI」的 HTTP：路径是 <code>/v1/chat/completions</code> 或 <code>/v1/completions</code>，请求里有 <code>model</code>、<code>messages</code> 或 <code>prompt</code>、<code>temperature</code>、<code>max_tokens</code>、<code>stream</code>。TGI 把它做成 Messages API 开关，vLLM 做成 <code>api_server</code>，LMDeploy 做成 <code>serve api_server</code>，MindIE EndPoint 把该路径列进支持表。本篇写这层协议在工程上承诺了什么、故意没承诺什么。它不是 IETF RFC，也没有一篇叫「OpenAI Compatible API」的经典论文；行为以各引擎文档与 OpenAI 公开的字段说明为准，不要编造协议的 arXiv。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>业务侧已经用官方 SDK、LangChain、自研网关对着云厂商的 Chat Completions 写完了。若每个开源引擎只暴露私有 <code>/generate</code>，适配成本会按引擎数线性涨。反过来，若声称「100% OpenAI 兼容」却在 <code>tools</code>、<code>logprobs</code>、多模态 <code>content</code> 数组、<code>seed</code> 上静默丢字段，线上会以「偶发拒答、偶发不流式」的方式失败。需要一份清晰的契约：哪些字段是生成的最小完备集，哪些是扩展，哪些必须在服务端用 <a href="/llm/chat-template">chat template</a> 落到真正的 token 序列。</p><p>另一半问题是 Completions 与 Chat Completions 混用。前者吃原始 <code>prompt</code> 字符串，后者吃带 <code>role</code> 的 <code>messages</code>。基座模型与指令模型对这两种前缀的分布不同。网关若把 chat 请求拼成裸 prompt 却不走模型卡上的模板，表现会像「换引擎后变傻」，根因是协议层帮倒忙。</p><h3 id="信封兼容与语义兼容" tabindex="-1">信封兼容与语义兼容 <a class="header-anchor" href="#信封兼容与语义兼容" aria-label="Permalink to &quot;信封兼容与语义兼容&quot;">​</a></h3><p>信封兼容：URL、JSON 字段名、流式时的 SSE 帧形状、错误对象大概能被现有客户端解析。语义兼容：同样的 <code>messages</code> 在两个后端 tokenize 后是同一串 token，采样字段的默认值相同，工具调用的参数 JSON 能被同一套 schema 校验。生产事故几乎都出在语义层——默认 <code>temperature</code>、是否丢弃 think 标签、EOS 与 stop 的优先级——而客户端 SDK 只检查信封。</p><p><span class="marginnote"><code>model</code> 字段在兼容服务里常常是路由键，不是权重哈希。同一字符串在 A 集群指向 7B 量化，在 B 集群指向 70B，是运维约定。客户端不应用 <code>model</code> 去推断上下文长度或工具调用能力。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>最小聊天请求是：<code>POST /v1/chat/completions</code>，body 含 <code>model</code> 与 <code>messages</code>（至少一条 <code>user</code>）。非流式返回一个 JSON，<code>choices[0].message.content</code> 为完整回复，<code>usage</code> 里是 prompt / completion token 计数。<code>stream: true</code> 时改为 <code>text/event-stream</code>，每帧一个 chunk，最后一帧习惯上带结束标记，细节见 <a href="/llm/sse-cancel">流式输出与取消</a>。Completions 路径 <code>/v1/completions</code> 仍被 vLLM 等保留，给续写与旧客户端用；新应用应默认走 chat，以便模板与多轮角色可审计。</p><p>服务端必须在引擎之前做三件事：把 <code>messages</code> 经 tokenizer 的 <code>apply_chat_template</code> 变成字符串或 token；施加 <code>max_tokens</code> 与上下文窗的交；把 <code>stop</code>、<code>presence_penalty</code> 一类采样参数翻译成引擎内部的 <code>SamplingParams</code>。缺模板时，兼容层若擅自拼接 <code>User:</code> / <code>Assistant:</code>，等于发明了第三套格式。多模态消息把 <code>content</code> 从字符串变成 part 列表（text / image_url 等），引擎要能把图像编码进前缀；不支持时应返回明确 4xx，而不是忽略图片只读文字。</p>',12)),(o(),l(r,null,{default:c(()=>[p(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22POST%20%2Fv1%2Fchat%2Fcompletions%22%5D%20--%3E%20VAL%5B%22%E6%A0%A1%E9%AA%8C%E5%AD%97%E6%AE%B5%E4%B8%8E%E9%95%BF%E5%BA%A6%22%5D%0A%20%20VAL%20--%3E%20TPL%5B%22chat%20template%20%E2%86%92%20token%22%5D%0A%20%20TPL%20--%3E%20ENG%5B%22%E5%BC%95%E6%93%8E%20prefill%20%2F%20decode%22%5D%0A%20%20ENG%20--%3E%20S%7B%22stream%3F%22%7D%0A%20%20S%20--%3E%7C%E5%90%A6%7C%20JSON%5B%22JSON%20choices%20%2B%20usage%22%5D%0A%20%20S%20--%3E%7C%E6%98%AF%7C%20SSE%5B%22SSE%20chunk%20%E6%B5%81%22%5D%0A"})]),fallback:c(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h3 id="工具调用与结构化输出" tabindex="-1">工具调用与结构化输出 <a class="header-anchor" href="#工具调用与结构化输出" aria-label="Permalink to &quot;工具调用与结构化输出&quot;">​</a></h3><p>OpenAI 后来在同一路径上加了 <code>tools</code> / <code>tool_choice</code>。兼容引擎若实现，通常是约束解码或后处理 JSON，而不是再训一个隐藏的工具头。TGI 文档把 guidance / schema 当成生成功能；这与「HTTP 字段叫 <code>tools</code>」可以对接，也可以各做各的。未实现时，正确行为是拒绝请求或忽略并在文档声明，而不是生成一段看起来像函数调用、却不能通过 schema 的文本。结构化输出（JSON mode）同样是解码约束，不是协议本身的魔法。</p><p>鉴权头 <code>Authorization: Bearer</code> 在自建集群里往往只是网关的占位；引擎进程可能完全不读它。不要把「兼容 OpenAI」理解成兼容了云厂商的计费、组织与限流语义。限流、API key 轮转、审计日志属于网关，应写在兼容层之外。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>协议能成为事实标准，是因为它把「对话状态」放在客户端：每次请求带上完整 <code>messages</code>，服务端可以无会话。这对无状态水平扩展友好，却把历史重复 tokenize、重复 prefill 的成本甩给引擎——于是需要前缀缓存与 <a href="/llm/kv-aware-routing">KV 感知路由</a>。流式则把 TTFT 从「整段结束」改成「首 token」，但 <code>usage</code> 往往要到流结束才完整，网关不能在第一个 chunk 上做精确计费。</p><p><code>n</code>、<code>best_of</code> 会把一条 HTTP 请求放大成多条内部序列，显存与计费都按内部序列走。兼容层若只在 HTTP 并发计数上做配额，会被 <code>n&gt;1</code> 打穿。<code>logprobs</code> 改变返回体积与内核是否物化完整分布，默认应关。<code>seed</code> 在张量并行与连续批下通常不能保证跨引擎比特一致，只能当弱可复现，见 <a href="/llm/tensor-parallel">张量并行</a> 里 All-Reduce 次序对浮点的影响。</p><p><span class="marginnote">TGI 自有 HTTP API 与 Messages API 并存。只测 <code>/generate</code> 不能证明 OpenAI 客户端可用；只测 chat 也不能证明旧 Completions 脚本可用。兼容矩阵要按路径列，不要按项目名列。</span></p><h3 id="错误形状与版本漂移" tabindex="-1">错误形状与版本漂移 <a class="header-anchor" href="#错误形状与版本漂移" aria-label="Permalink to &quot;错误形状与版本漂移&quot;">​</a></h3><p>OpenAI 风格错误体一般是 <code>{&quot;error&quot;: {&quot;message&quot;: ..., &quot;type&quot;: ..., &quot;code&quot;: ...}}</code>。引擎用 FastAPI 默认 422 或 HTML 错误页时，官方 SDK 会解析失败，表现为「连不上」而不是「参数非法」。兼容工作有一半是把校验错误翻译成这层信封。字段还会漂移：<code>max_tokens</code> 与 <code>max_completion_tokens</code>、<code>functions</code> 与 <code>tools</code>。兼容层应声明自己对齐的文档日期，而不是声称追踪最新云 API。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>兼容协议不包含模型许可、内容安全、检索增强或代理循环。它也不规定 KV 如何分页、是否多 LoRA。那些是引擎与调度的事，见 <a href="/llm/multi-lora-serving">多 LoRA 服务</a>。客户端 SDK 的默认超时、代理的缓冲（Nginx 默认可能攒满 SSE）会破坏流式语义，这是运维问题，协议文本写不清楚。</p><p>不要用云厂商的模型名去打开源兼容端，除非路由表显式做了别名。不要假设 <code>/v1/embeddings</code>、<code>/v1/audio/transcriptions</code>、<code>/v1/images/generations</code> 随 chat 一起存在；MindIE 把视图生成放在另一套件，就是反例。协议最小核心就是：聊天或补全、可选流式、可选用量。每多一个路径，就多一张测试表。</p><p><span class="marginnote">引用 OpenAI 公开 API 参考、Hugging Face TGI Messages API、昇腾 MindIE EndPoint 列表与各引擎的 OpenAI serving 说明。没有单独的标准编号；互操作靠对照字段，不靠伪造论文。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>OpenAI 兼容指 HTTP 信封与常见字段，不是模型等价，也不是完整云平台语义。</li><li>Chat Completions 必须经官方 chat template 再进引擎；不要在网关里发明角色拼接。</li><li>流式、工具调用、多模态、logprobs 是可选项，未实现应显式失败。</li><li>无状态 <code>messages</code> 便于扩缩，但把前缀成本交给 KV 缓存与路由。</li><li>错误体与默认采样值属于兼容性的一部分，不是装饰。</li><li>出处：OpenAI API 参考；TGI / vLLM / LMDeploy / MindIE 各自的兼容层文档。</li></ul>',15))])}const P=d(m,[["render",h]]);export{E as __pageData,P as default};
